#include <stdio.h>
int main(void) {
    float temperature = 0.0f;
    int samples = 0, below = 0;
    while (scanf("%f", &temperature) == 1) {
        samples++;
        if (temperature < 0.0f) {
            below++;
        }
    }
    if (samples > 0) {
        double percent = 100.0 * below / samples;
        printf("count=%d below=%d percent=%.1f\n", samples, below, percent);
    } else {
        printf("no samples\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int ch = getchar();
    while (ch != EOF && ch != '\n') {
        if (ch == ' ') {
            putchar(ch);
        } else {
            if (ch >= 126) return 1;
            putchar(ch + 1);
        }
        ch = getchar();
    }
    if (ch == '\n') putchar(ch);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void) {
    int ch = getchar();
    while (ch != EOF && ch != '\n') {
        if (isalpha(ch)) {
            putchar(ch + 1);
        } else {
            putchar(ch);
        }
        ch = getchar();
    }
    if (ch == '\n') putchar(ch);
    return 0;
}

#include <stdio.h>
int main(void) {
    double used = 0.0;
    if (scanf("%lf", &used) != 1 || used < 0.0) return 1;
    double bill = 0.0;
    if (used <= 10.0) {
        bill = used;
    } else if (used <= 20.0) {
        bill = 10.0 + (used - 10.0) * 2.0;
    } else if (used <= 30.0) {
        bill = 30.0 + (used - 20.0) * 3.0;
    } else {
        bill = 60.0 + (used - 30.0) * 4.0;
    }
    printf("bill=%.2f\n", bill);
    return 0;
}

#include <stdio.h>
int main(void) {
    int number = 0;
    if (scanf("%d", &number) != 1 || number < 2 || number > 100) return 1;
    int prime = 1;
    for (int divisor = 2; divisor <= number / divisor; divisor++) {
        if (number % divisor == 0) {
            if (divisor == number / divisor) {
                printf("single=%d\n", divisor);
            } else {
                printf("pair=%d,%d\n", divisor, number / divisor);
            }
            prime = 0;
        }
    }
    if (prime) printf("prime\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int ch = getchar();
    int count = 0;
    while (ch != EOF && ch != '.') {
        if (ch != '\'' && ch != '"') {
            count++;
        }
        ch = getchar();
    }
    printf("nonquote=%d\n", count);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void) {
    int ch = getchar();
    int previous = '\n';
    int characters = 0, words = 0, lines = 0;
    int inside = 0;
    while (ch != EOF && ch != '|') {
        characters++;
        if (ch == '\n') lines++;
        if (isspace(ch)) {
            inside = 0;
        } else if (!inside) {
            words++;
            inside = 1;
        }
        previous = ch;
        ch = getchar();
    }
    int partial = characters > 0 && previous != '\n';
    printf("chars=%d words=%d lines=%d partial=%d\n", characters, words, lines, partial);
    return 0;
}

#include <stdio.h>
int main(void) {
    const int coverage = 5;
    int area = 0;
    if (scanf("%d", &area) != 1 || area < 0) return 1;
    int cans = area / coverage;
    cans += area % coverage == 0 ? 0 : 1;
    printf("%d %s\n", cans, cans == 1 ? "can" : "cans");
    return 0;
}

#include <stdio.h>
int main(void) {
    double value = 0.0;
    double sum = 0.0, lowest = 10.0, highest = 0.0;
    int accepted = 0;
    while (scanf("%lf", &value) == 1) {
        if (value < 0.0 || value > 10.0) {
            printf("skip\n");
            continue;
        }
        lowest = value < lowest ? value : lowest;
        highest = value > highest ? value : highest;
        sum += value;
        accepted++;
    }
    if (accepted > 0) {
        printf("n=%d mean=%.1f min=%.1f max=%.1f\n", accepted, sum / accepted, lowest, highest);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    double length = 0.0, width = 0.0;
    while (scanf("%lf", &length) == 1) {
        if (scanf("%lf", &width) != 1) break;
        if (length <= 0.0 || width <= 0.0) return 1;
        printf("area=%.1f\n", length * width);
    }
    printf("done\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int first = getchar();
    while (first != EOF && first != '#') {
        if (first == '\n') {
            first = getchar();
            continue;
        }
        if (first >= 'a' && first <= 'z') {
            switch (first) {
                case 'a': printf("ant\n"); break;
                case 'c': printf("cat\n"); break;
                default: printf("unknown\n"); break;
            }
        } else {
            printf("lowercase\n");
        }
        int tail = getchar();
        while (tail != EOF && tail != '\n') tail = getchar();
        if (tail == EOF) break;
        first = getchar();
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 0, e = 0, i = 0, o = 0, u = 0;
    int ch = getchar();
    while (ch != EOF && ch != '#') {
        switch (ch) {
            case 'a': case 'A': a++; break;
            case 'e': case 'E': e++; break;
            case 'i': case 'I': i++; break;
            case 'o': case 'O': o++; break;
            case 'u': case 'U': u++; break;
            default: break;
        }
        ch = getchar();
    }
    printf("%d %d %d %d %d\n", a, e, i, o, u);
    return 0;
}

