    if (scanf("%d", &received) != 1) return 1;
    int bounded = received;
    if (received < 0) {
        bounded = 0;
    } else {
        if (received > 6) {
            bounded = 6;
        } else {
            bounded = received;
        }
    }
    printf("%d\n", bounded);
    return 0;
}

