#include <stdio.h>
int main(void) {
    int selected = 0;
    if (scanf("%d", &selected) != 1) return 1;
    int code = -1;
    switch (selected) {
        case 0: code = 100; break;
        case 1: code = 200; break;
        case 2: code = 300; break;
        default: code = -1; break;
    }
    if (code != -1) code += 4;
    printf("%d\n", code);
    return 0;
}
